BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY; SET LOCAL search_path=pg_catalog; SET LOCAL statement_timeout='20s'; SELECT jsonb_build_object('observedAt',clock_timestamp(),'readOnly',current_setting('transaction_read_only'),'historyRpc',to_regprocedure('public.save_calculation_history_atomic(uuid,text,integer,jsonb,jsonb,uuid)')::text,'scenarioRpc',to_regprocedure('public.save_project_scenario_atomic(uuid,uuid,uuid,text,uuid)')::text,'historyTable',to_regclass('public.calculation_history')::text,'scenariosTable',to_regclass('public.saved_scenarios')::text,'projectsTable',to_regclass('public.calculation_projects')::text,'scopedLocks',(SELECT count(*) FROM pg_locks WHERE relation IN(SELECT c.oid FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN('calculator_catalog_admin','calculator_qa_checks','calculator_review_events','calculator_bulk_jobs','calculator_source_evidence','admin_alerts','platform_admins')) AND pid IS DISTINCT FROM pg_backend_pid()),'preparedTransactions',(SELECT count(*) FROM pg_prepared_xacts WHERE database=current_database()),'catalogRowDigest',(SELECT encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(c) ORDER BY c.id),'[]'::jsonb)::text,'UTF8')),'hex') FROM public.calculator_catalog_admin c),'publishedCount',(SELECT count(*) FROM public.calculator_catalog_admin WHERE lifecycle='published')) AS evidence; COMMIT;
